<?php
declare(strict_types=1);
// Bounded row changes, never arbitrary SQL. Drafts are private, encrypted and short lived.
function agentMcpWrites(array $p):array {return json_decode($p['write_selection']??'{}',true)?:[];}
function agentMcpWriteSelection(mixed $v,array $read):array {
    $v=studioRecord($v);if(count($v)>20)fail(422,'Höchstens 20 Tabellen freigeben.');$out=[];
    foreach($v as $table=>$value){if(!isset($read[$table]))fail(422,'Schreibrechte benötigen eine lesend freigegebene Tabelle.');$value=studioRecord($value);$cols=labList($value['columns']??[],50);foreach($cols as $col){if(!is_string($col))fail(422,'Ungültige Schreibspalte.');identifier($col);}if(!$cols||array_diff($cols,$read[$table])||count(array_unique($cols))!==count($cols))fail(422,'Nur lesend freigegebene Spalten können schreibbar sein.');foreach(['insert','update'] as $op)if(!is_bool($value[$op]??null))fail(422,'Anlegen und Ändern bitte ausdrücklich auswählen.');if(!$value['insert']&&!$value['update'])fail(422,'Mindestens eine Schreiboperation auswählen.');$out[$table]=['columns'=>$cols,'insert'=>$value['insert'],'update'=>$value['update']];}return $out;
}
function agentMcpWriteMetadata(PDO $pdo,string $table,array $read,array $write):array {
    $s=$pdo->prepare('SELECT TABLE_TYPE,ENGINE FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?');$s->execute([$table]);$info=$s->fetch();if(!$info||$info['TABLE_TYPE']!=='BASE TABLE'||strtolower($info['ENGINE']??'')!=='innodb')fail(422,'Schreiben benötigt eine InnoDB-Tabelle; Views sind nicht schreibbar.');
    $meta=tableColumns($pdo,$table);$keys=[];$columns=[];foreach($meta as $col){$columns[$col['Field']]=$col;if($col['Key']==='PRI')$keys[]=$col['Field'];}
    if(!$keys||array_diff($keys,$read))fail(422,'Zum Schreiben alle Primärschlüssel-Spalten auch lesend freigeben.');
    foreach($write['columns'] as $col)if(!isset($columns[$col])||preg_match('/(?:GENERATED|auto_increment)/i',$columns[$col]['Extra']??''))fail(422,'Generierte Spalten und automatische IDs sind nicht schreibbar.');
    return ['keys'=>$keys,'columns'=>$columns];
}
function agentMcpWritePlan(array $p,array $a):array {
    if(array_diff(array_keys($a),['operation','table','values','key']))fail(422,'Unbekannte Änderungsparameter.');$op=studioEnum($a['operation']??null,['insert','update']);$table=$a['table']??null;$writes=agentMcpWrites($p);if(!is_string($table)||!isset($writes[$table])||!$writes[$table][$op])fail(403,'Diese Schreiboperation wurde nicht freigegeben.');identifier($table);$values=studioRecord($a['values']??null);if(!$values||count($values)>50||array_diff(array_keys($values),$writes[$table]['columns']))fail(403,'Nur ausdrücklich schreibbar freigegebene Spalten sind erlaubt.');
    $key=studioRecord($a['key']??[]);if($op==='insert'&&$key)fail(422,'Beim Anlegen gehören Werte in values, nicht in key.');foreach([$values,$key] as $record)foreach($record as $col=>$value){identifier((string)$col);if($value!==null&&!is_scalar($value)||is_float($value)&&!is_finite($value)||is_string($value)&&(strlen($value)>10000||str_contains($value,"\0")))fail(422,'Zellen benötigen begrenzte einfache Werte.');}if(strlen(labJson([$values,$key]))>24000)fail(413,'Die Änderung ist größer als 24 KB.');return ['operation'=>$op,'table'=>$table,'values'=>$values,'key'=>$key];
}
function agentMcpWriteRow(PDO $pdo,array $plan,array $cols,array $keys,bool $lock=false):array {
    if(array_diff($keys,array_keys($plan['key']))||array_diff(array_keys($plan['key']),$keys)||array_filter($plan['key'],fn($v)=>$v===null||$v===''))fail(422,'Ändern benötigt den vollständigen Primärschlüssel eines Datensatzes.');
    $s=$pdo->prepare('SELECT '.implode(',',array_map('identifier',$cols)).' FROM '.identifier($plan['table']).' WHERE '.implode(' AND ',array_map(fn($k)=>identifier($k).' <=> ?',$keys)).' LIMIT 2'.($lock?' FOR UPDATE':''));$s->execute(array_map(fn($k)=>$plan['key'][$k],$keys));$rows=$s->fetchAll();if(count($rows)!==1)fail(409,'Der Datensatz wurde nicht eindeutig gefunden. Neu lesen und erneut vorbereiten.');if(strlen(labJson($rows[0]))>32000)fail(413,'Datensatz zu groß für eine Änderungsvorschau.');return $rows[0];
}
function agentMcpWriteAuthorize(array $u,array $p):array {
    $freshUser=one('SELECT * FROM users WHERE id=?',[$u['id']]);if(!$freshUser||!$freshUser['active']||$freshUser['must_change_password']||(int)$freshUser['auth_version']!==(int)$u['auth_version'])fail(403,'Der Zugang wurde geändert oder deaktiviert.');$u=$freshUser;agentMcpRights($u);needFeature($u,'mcp_write');if(isset($p['_oauth_grant'])){$grant=one('SELECT * FROM mcp_oauth_grants WHERE id=?',[$p['_oauth_grant']]);$access=one('SELECT * FROM mcp_oauth_access WHERE hash=?',[$p['_oauth_access']]);if(!$grant||!$access||$access['grant_id']!==$grant['id']||(int)$access['expires']<=time()||$grant['revoked']||(int)$grant['expires']<=time()||!str_contains($grant['scope'],'db:write'))fail(403,'Die Schreib-Einwilligung wurde widerrufen oder ist abgelaufen.');}if(($p['write_allowed']??true)!==true||!agentMcpWrites($p))fail(403,'Diese Verbindung besitzt keine Schreibfreigabe.');$fresh=agentMcpProfile($u);if(isset($p['_personal_hash'])&&(!hash_equals($fresh['token_hash']??'',$p['_personal_hash'])||(int)$fresh['token_expires']<=time()))fail(403,'Der persönliche Schlüssel wurde widerrufen.');if((int)$fresh['version']!==(int)($p['version']??-1)||!$fresh['enabled'])fail(403,'Die Freigabe wurde geändert oder abgeschaltet.');$conn=agentMcpConnection($u,$fresh['project_id']);if(!hash_equals($p['connection_hash']??'',agentMcpConnectionHash($conn)))fail(403,'Die Datenbankverbindung wurde geändert.');return $conn;
}
function agentMcpPrepareChange(array $u,array $p,array $a,?PDO $pdo=null):array {
    $conn=agentMcpWriteAuthorize($u,$p);$plan=agentMcpWritePlan($p,$a);$pdo??=mysqlConnection($u,$conn);$read=json_decode($p['selection'],true)[$plan['table']];$meta=agentMcpWriteMetadata($pdo,$plan['table'],$read,agentMcpWrites($p)[$plan['table']]);
    if($plan['operation']==='update'&&array_intersect(array_keys($plan['values']),$meta['keys']))fail(422,'Primärschlüssel können nicht geändert werden.');
    foreach($plan['values'] as $col=>$v)if($v===null&&$meta['columns'][$col]['Null']!=='YES')fail(422,'Diese Spalte darf nicht leer sein: '.$col);
    if($plan['operation']==='insert')foreach($meta['columns'] as $col=>$m)if($m['Null']==='NO'&&$m['Default']===null&&!preg_match('/(?:GENERATED|auto_increment)/i',$m['Extra']??'')&&!array_key_exists($col,$plan['values']))fail(422,'Pflichtspalte fehlt oder ist nicht schreibbar freigegeben: '.$col);
    $before=$plan['operation']==='update'?agentMcpWriteRow($pdo,$plan,$read,$meta['keys']):null;$plan['before']=$before;
    $id=id();$result=['change'=>$id,'operation'=>$plan['operation'],'table'=>$plan['table'],'key'=>(object)$plan['key'],'before'=>$before,'after'=>$before===null?(object)$plan['values']:(object)[...$before,...$plan['values']],'expiresIn'=>600,'applied'=>false,'next'=>'Review the proposed change with the user. Only after approval call db.apply_change with this change ID and confirm=true.'];if(strlen(labJson($result))>64000)fail(413,'Die Änderungsvorschau ist größer als 64 KB. Weniger Spalten freigeben.');transaction(function()use($u,$p,$plan,$id){query('DELETE FROM agent_mcp_changes WHERE (expires<? AND status="pending") OR (expires<? AND status<>"executing")',[time(),time()-86400]);if((int)query('SELECT COUNT(*) FROM agent_mcp_changes WHERE user_id=?',[$u['id']])->fetchColumn()>=5000)fail(429,'Zu viele Änderungsbelege. Nach Ablauf der Aufbewahrungsfrist erneut versuchen.');if((int)query('SELECT COUNT(*) FROM agent_mcp_changes WHERE user_id=? AND status IN("pending","executing","uncertain")',[$u['id']])->fetchColumn()>=30)fail(429,'Zu viele offene Änderungsvorschauen. Abgelaufene Vorschauen werden bereinigt.');query('INSERT INTO agent_mcp_changes(id,user_id,profile_version,connection_hash,payload,expires) VALUES(?,?,?,?,?,?)',[$id,$u['id'],$p['version'],$p['connection_hash'],encryptSecret(labJson($plan)),time()+600]);});
    return $result;
}
function agentMcpApplyChange(array $u,array $p,array $a,?PDO $pdo=null):array {
    $conn=agentMcpWriteAuthorize($u,$p);if(array_diff(array_keys($a),['change','confirm'])||($a['confirm']??null)!==true||!is_string($a['change']??null)||!preg_match('/^[a-f0-9]{32}$/D',$a['change']))fail(422,'Die Änderung muss ausdrücklich mit change und confirm=true bestätigt werden.');
    $change=transaction(function()use($u,$p,$a){$c=one('SELECT * FROM agent_mcp_changes WHERE id=? AND user_id=?',[$a['change'],$u['id']]);if(!$c)fail(404,'Änderung nicht gefunden.');if((int)$c['profile_version']!==(int)$p['version']||!hash_equals($c['connection_hash'],$p['connection_hash']))fail(403,'Diese Vorschau gehört zu einer früheren Freigabe.');if($c['status']==='done')return $c;if($c['status']!=='pending')fail(409,'Dieser Aufruf wurde bereits begonnen. Nicht erneut ausführen; Datenbankstand zuerst prüfen.');if((int)$c['expires']<time())fail(409,'Vorschau abgelaufen. Änderung neu vorbereiten.');query('UPDATE agent_mcp_changes SET status="executing" WHERE id=?',[$c['id']]);return $c;});
    if($change['status']==='done')return json_decode(decryptSecret($change['result']),true,32,JSON_THROW_ON_ERROR);
    $committed=false;$started=false;
    try{
        $pdo??=mysqlConnection($u,$conn);$stored=json_decode(decryptSecret($change['payload']),true,32,JSON_THROW_ON_ERROR);$plan=agentMcpWritePlan($p,array_intersect_key($stored,array_flip(['operation','table','values','key'])));$read=json_decode($p['selection'],true)[$plan['table']];$meta=agentMcpWriteMetadata($pdo,$plan['table'],$read,agentMcpWrites($p)[$plan['table']]);
        if($plan['operation']==='update'&&array_intersect(array_keys($plan['values']),$meta['keys']))fail(422,'Primärschlüssel können nicht geändert werden.');
        $pdo->exec("SET SESSION sql_mode=CONCAT_WS(',',@@sql_mode,'STRICT_ALL_TABLES')");$pdo->exec('SET SESSION innodb_lock_wait_timeout=5');$pdo->beginTransaction();$started=true;
        if($plan['operation']==='update'){$current=agentMcpWriteRow($pdo,$plan,$read,$meta['keys'],true);if($current!==$stored['before'])fail(409,'Der Datensatz wurde seit der Vorschau verändert. Änderung neu vorbereiten.');}
        // Recheck current authorization and profile immediately before the bounded database mutation.
        agentMcpWriteAuthorize($u,$p);$cols=array_keys($plan['values']);$table=identifier($plan['table']);
        if($plan['operation']==='insert'){$sql='INSERT INTO '.$table.' ('.implode(',',array_map('identifier',$cols)).') VALUES ('.implode(',',array_fill(0,count($cols),'?')).')';$values=array_values($plan['values']);}
        else{$sql='UPDATE '.$table.' SET '.implode(',',array_map(fn($c)=>identifier($c).'=?',$cols)).' WHERE '.implode(' AND ',array_map(fn($k)=>identifier($k).' <=> ?',$meta['keys'])).' LIMIT 1';$values=[...array_values($plan['values']),...array_map(fn($k)=>$plan['key'][$k],$meta['keys'])];}
        $stmt=$pdo->prepare($sql);$stmt->execute(array_map(fn($v)=>is_bool($v)?(int)$v:$v,$values));$affected=$stmt->rowCount();if($affected>1)fail(409,'Mehr als ein Datensatz betroffen. Änderung abgebrochen.');agentMcpWriteAuthorize($u,$p);
        $result=['change'=>$change['id'],'operation'=>$plan['operation'],'table'=>$plan['table'],'affected'=>$affected,'applied'=>true];
        if($plan['operation']==='insert'&&count($meta['keys'])===1&&str_contains($meta['columns'][$meta['keys'][0]]['Extra']??'','auto_increment'))$result['key']=(object)[$meta['keys'][0]=>$pdo->lastInsertId()];else $result['key']=(object)($plan['operation']==='insert'?array_intersect_key($plan['values'],array_flip($meta['keys'])):$plan['key']);
        // Keep the receipt in "executing" if COMMIT or receipt persistence has an ambiguous outcome.
        $committed=true;$pdo->commit();query('UPDATE agent_mcp_changes SET status="done",payload="",result=? WHERE id=?',[encryptSecret(labJson($result)),$change['id']]);return $result;
    }catch(Throwable $e){$rolledBack=false;if(!$committed){if($started&&$pdo?->inTransaction()){try{$pdo->rollBack();$rolledBack=true;}catch(Throwable){}}elseif(!$started)$rolledBack=true;}
        try{query('UPDATE agent_mcp_changes SET status=?,payload=CASE WHEN ? THEN ? ELSE payload END WHERE id=?',[$rolledBack?'failed':'uncertain',(int)$rolledBack,'',$change['id']]);}catch(Throwable){}
        if(!$rolledBack)fail(409,'Das Ergebnis ist unklar. Nicht wiederholen; Datenbankstand zuerst prüfen.');if($e instanceof ApiError)throw $e;if($e instanceof PDOException)mysqlError($e);throw $e;
    }
}
function agentMcpWriteTools(array $p):array {
    $writes=agentMcpWrites($p);if(!$writes||($p['write_allowed']??true)!==true)return [];
    $security=[['type'=>'oauth2','scopes'=>['db:read','db:write']]];$base=['securitySchemes'=>$security,'_meta'=>['securitySchemes'=>$security],'annotations'=>['readOnlyHint'=>false,'destructiveHint'=>false,'idempotentHint'=>false,'openWorldHint'=>false]];
    return [$base+['name'=>'db.prepare_change','description'=>'Preview one insert or update in explicitly writable columns. Does not modify the database. Show before/after to the user before applying. For updates key must contain every primary-key column. Never delete or change primary keys.','inputSchema'=>['type'=>'object','properties'=>['operation'=>['type'=>'string','enum'=>['insert','update']],'table'=>['type'=>'string','enum'=>array_keys($writes)],'values'=>['type'=>'object','description'=>'Only columns explicitly listed as writable by db.list_tables. Values must be scalar or null.'],'key'=>['type'=>'object','description'=>'Update only: complete primary key.']],'required'=>['operation','table','values'],'additionalProperties'=>false]],
        ['name'=>'db.apply_change','description'=>'Apply the exact previously reviewed change. Call only after user approval, with confirm=true. One row only; retries of the same completed change ID return the receipt. If outcome is uncertain do not retry or create a replacement change; inspect the database first.','securitySchemes'=>$security,'_meta'=>['securitySchemes'=>$security],'annotations'=>['readOnlyHint'=>false,'destructiveHint'=>true,'idempotentHint'=>true,'openWorldHint'=>false],'inputSchema'=>['type'=>'object','properties'=>['change'=>['type'=>'string','pattern'=>'^[a-f0-9]{32}$'],'confirm'=>['type'=>'boolean','const'=>true]],'required'=>['change','confirm'],'additionalProperties'=>false]]];
}
